package sqlite

import (
	"context"
	"database/sql"
	"embed"
	"errors"
	"fmt"
	"net/url"
	"os"
	"path/filepath"
	"time"

	"github.com/araihu/oie/internal/adapters/sqlite/dbgen"
	"github.com/araihu/oie/internal/domain"
)

// The restore scripts join an attached, validated snapshot with the live
// schema. Ordinary single-database queries are generated by sqlc.
//
//go:embed restore/*.sql
var restoreSQL embed.FS

const (
	firstRestoreSchema  = 36
	newestRestoreSchema = 44
)

type RestoreSummary struct {
	Accounts      int64 `json:"accountsAdded"`
	Conversations int64 `json:"conversationsAdded"`
	Messages      int64 `json:"messagesAdded"`
	PausedSends   int64 `json:"sendsPaused"`
	MediaFiles    int   `json:"mediaFilesAdded"`
}

func RestoreProfileBackup(ctx context.Context, dir, filename string, newID domain.ID) (_ RestoreSummary, err error) {
	dir, err = filepath.Abs(dir)
	if err != nil {
		return RestoreSummary{}, err
	}
	scratch, err := os.MkdirTemp("", "oie-restore-backup-")
	if err != nil {
		return RestoreSummary{}, err
	}
	defer func() { _ = os.RemoveAll(scratch) }()
	manifest, err := readBackup(ctx, filename, scratch)
	if err != nil {
		return RestoreSummary{}, fmt.Errorf("read backup: %w", err)
	}
	archivePath := filepath.Join(scratch, backupDatabaseName)
	if err := checkRestoreDatabase(ctx, archivePath); err != nil {
		return RestoreSummary{}, err
	}
	store, err := Open(ctx, dir, newID)
	if err != nil {
		return RestoreSummary{}, fmt.Errorf("open destination profile: %w", err)
	}
	defer func() { err = errors.Join(err, store.Close()) }()
	return store.mergeBackup(ctx, archivePath, scratch, manifest, time.Now().UTC())
}

func checkRestoreDatabase(ctx context.Context, filename string) (err error) {
	source, err := openBackupDatabase(filename, "ro")
	if err != nil {
		return err
	}
	defer func() { err = errors.Join(err, source.Close()) }()
	var version int
	var dirty bool
	if err := source.QueryRowContext(ctx, "SELECT version,dirty FROM schema_migrations").Scan(&version, &dirty); err != nil {
		return fmt.Errorf("read backup schema version: %w", err)
	}
	if dirty || version < firstRestoreSchema || version > newestRestoreSchema {
		return fmt.Errorf("unsupported backup database version %d", version)
	}
	var integrity string
	if err := source.QueryRowContext(ctx, "PRAGMA quick_check(1)").Scan(&integrity); err != nil {
		return err
	}
	if integrity != "ok" {
		return errors.New("backup database failed integrity verification")
	}
	rows, err := source.QueryContext(ctx, "PRAGMA foreign_key_check")
	if err != nil {
		return err
	}
	defer func() { _ = rows.Close() }()
	if rows.Next() {
		return errors.New("backup database has broken references")
	}
	return rows.Err()
}

func restoreScript(name string) string {
	data, err := restoreSQL.ReadFile("restore/" + name + ".sql")
	if err != nil {
		panic(err)
	}
	return string(data)
}

func (s *Store) mergeBackup(ctx context.Context, archivePath, scratch string, manifest backupManifest, now time.Time) (result RestoreSummary, err error) {
	conn, err := s.db.Conn(ctx)
	if err != nil {
		return result, err
	}
	defer func() { err = errors.Join(err, conn.Close()) }()
	uri := url.URL{Scheme: "file", Path: archivePath, RawQuery: "mode=ro&immutable=1"}
	if _, err := conn.ExecContext(ctx, "ATTACH DATABASE ? AS backup", uri.String()); err != nil {
		return result, err
	}
	defer func() {
		_, detachErr := conn.ExecContext(context.WithoutCancel(ctx), "DETACH DATABASE backup")
		err = errors.Join(err, detachErr)
	}()
	if err := validateRestoreTables(ctx, conn); err != nil {
		return result, err
	}

	var hasRecoveredRows, recoveredSchemaValid bool
	if err := conn.QueryRowContext(ctx, restoreScript("recovered_schema")).Scan(&hasRecoveredRows, &recoveredSchemaValid); err != nil {
		return result, err
	}
	if hasRecoveredRows && !recoveredSchemaValid {
		return result, errors.New("backup has an invalid recovered sends schema")
	}
	var hasDeletedAccounts, hasRecoveredHistory, hasOwnEchoes, hasDownloadCleanup, hasDownloadLineage, extendedSchemaValid bool
	if err := conn.QueryRowContext(ctx, restoreScript("extended_schema")).Scan(&hasDeletedAccounts, &hasRecoveredHistory, &hasOwnEchoes, &hasDownloadCleanup, &hasDownloadLineage, &extendedSchemaValid); err != nil {
		return result, err
	}
	if !extendedSchemaValid {
		return result, errors.New("backup has an invalid restore evidence schema")
	}
	tx, err := conn.BeginTx(ctx, nil)
	if err != nil {
		return result, err
	}
	defer func() { _ = tx.Rollback() }()
	q := dbgen.New(tx)
	if err := q.AcquireWriteLock(ctx); err != nil {
		return result, err
	}
	if _, err := tx.ExecContext(ctx, restoreScript("hold_table")); err != nil {
		return result, err
	}
	if hasRecoveredRows {
		if _, err := tx.ExecContext(ctx, restoreScript("recovered_markers")); err != nil {
			return result, err
		}
	}
	if hasDeletedAccounts {
		if _, err := tx.ExecContext(ctx, restoreScript("deleted_accounts")); err != nil {
			return result, err
		}
	}
	if _, err := tx.ExecContext(ctx, restoreScript("markers")); err != nil {
		return result, err
	}
	if _, err := tx.ExecContext(ctx, restoreScript("select"), sql.Named("now_ms", now.UnixMilli())); err != nil {
		return result, fmt.Errorf("select backup entities: %w", err)
	}
	var conflict bool
	if err := tx.QueryRowContext(ctx, restoreScript("conflicts")).Scan(&conflict); err != nil {
		return result, err
	}
	if conflict {
		return result, errors.New("backup and destination have conflicting account, conversation, or message identities")
	}
	if err := tx.QueryRowContext(ctx, restoreScript("counts")).Scan(&result.Accounts, &result.Conversations, &result.Messages); err != nil {
		return result, err
	}
	facts, err := backupCorrectionFacts(ctx, tx)
	if err != nil {
		return result, err
	}
	if _, err := tx.ExecContext(ctx, restoreScript("entities")); err != nil {
		return result, fmt.Errorf("merge backup entities: %w", err)
	}
	if err := mergeRestoreRevisions(ctx, tx, q, now); err != nil {
		return result, fmt.Errorf("merge backup revisions: %w", err)
	}
	if hasOwnEchoes {
		if _, err := tx.ExecContext(ctx, restoreScript("own_echoes")); err != nil {
			return result, err
		}
	}
	if err := reconcileRestoredSendEvidence(ctx, tx, q, now); err != nil {
		return result, fmt.Errorf("reconcile backup send evidence: %w", err)
	}
	if err := q.RemoveReconciledRecoveredSends(ctx); err != nil {
		return result, err
	}
	pausedBefore, err := q.CountRecoveredSends(ctx)
	if err != nil {
		return result, err
	}
	if err := mergeRestoredQueue(ctx, tx, q, manifest.SourceEngine, hasRecoveredRows, hasRecoveredHistory); err != nil {
		return result, fmt.Errorf("quarantine recovered sends: %w", err)
	}
	if _, err := tx.ExecContext(ctx, restoreScript("hold_operations")); err != nil {
		return result, fmt.Errorf("preserve paused operation receipts: %w", err)
	}
	pausedAfter, err := q.CountRecoveredSends(ctx)
	if err != nil {
		return result, err
	}
	result.PausedSends = pausedAfter - pausedBefore
	if err := restoreDerivedHistory(ctx, tx, q, facts, now); err != nil {
		return result, err
	}

	committed := false
	defer func() {
		if !committed {
			_ = tx.Rollback()
			err = errors.Join(err, s.recoverRestoreMedia(context.WithoutCancel(ctx)))
		}
	}()
	published, err := s.restoreMedia(ctx, tx, scratch, manifest.Files, hasDownloadCleanup, hasDownloadLineage, now)
	if err != nil {
		return result, err
	}
	if _, err := tx.ExecContext(ctx, restoreScript("cleanup")); err != nil {
		return result, err
	}
	if err := tx.Commit(); err != nil {
		return result, err
	}
	committed = true
	_ = s.clearRestoreMediaJournal() // Startup rechecks committed references if cleanup was interrupted.
	result.MediaFiles = len(published)
	return result, nil
}

func validateRestoreTables(ctx context.Context, conn *sql.Conn) error {
	// Explicit column order and known ordinary tables are required. Archive
	// triggers, views and SQL instructions are never installed or executed.
	var valid bool
	if err := conn.QueryRowContext(ctx, restoreScript("schema")).Scan(&valid); err != nil {
		return err
	}
	if !valid {
		return errors.New("backup database schema does not match the supported tables")
	}
	return nil
}
